html:
{%- set is_ar = is_rtl() -%}
{%- set dir = "rtl" if is_ar else "ltr" -%}
{%- set labels = {
	"invoice_title": "فاتورة نقاط البيع" if is_ar else "POS Invoice",
	"invoice": "الفاتورة" if is_ar else "Invoice",
	"date": "التاريخ" if is_ar else "Date",
	"time": "الوقت" if is_ar else "Time",
	"cashier": "الكاشير" if is_ar else "Cashier",
	"customer": "العميل" if is_ar else "Customer",
	"pos_profile": "ملف نقطة البيع" if is_ar else "POS Profile",
	"status": "الحالة" if is_ar else "Status",
	"partial_payment": "دفعة جزئية" if is_ar else "PARTIAL PAYMENT",
	"item": "الصنف" if is_ar else "Item",
	"qty": "الكمية" if is_ar else "Qty",
	"price": "السعر" if is_ar else "Price",
	"amount": "المبلغ" if is_ar else "Amount",
	"free": "مجاني" if is_ar else "FREE",
	"discount": "خصم" if is_ar else "Discount",
	"subtotal": "المجموع الفرعي" if is_ar else "Subtotal",
	"tax": "الضريبة" if is_ar else "Tax",
	"total": "الإجمالي" if is_ar else "TOTAL",
	"payment_methods": "طرق الدفع" if is_ar else "Payment Methods",
	"total_paid": "إجمالي المدفوع" if is_ar else "Total Paid",
	"change": "الباقي" if is_ar else "Change",
	"balance_due": "المتبقي" if is_ar else "Balance Due",
	"thank_you": "شكراً لك" if is_ar else "Thank You",
	"powered_by": "بدعم من" if is_ar else "Powered by",
	"serial": "رقم تسلسلي" if is_ar else "S/N"
} -%}

<style>

    /* =========================================
       80mm Thermal Printer Settings
       ========================================= */

    @page {
        size: 80mm auto;
        margin: 0mm;
    }

    body {
        font-family: 'DejaVu Sans', 'Noto Naskh Arabic', Tahoma, Arial, sans-serif;
        width: 72mm;
        box-sizing: border-box;
        margin: 0 auto;
        padding: 6px;
        padding-bottom: 8px;
        font-size: 2.6mm;
        line-height: 1.35;
        direction: {{ dir }};
        background: #fff;
        color: #000;
    }

    /* =========================================
       Header
       ========================================= */

    .header-box {
        text-align: center;
        border: 2px solid #000;
        padding: 9px 5px;
        margin-bottom: 10px;
        background: #fff;
    }

    .header-logo {
        display: block;
        width: 88%;
        max-width: 58mm;
        margin: 0 auto 8px;
    }

    .invoice-label {
        display: inline-block;
        border: 1px solid #000;
        padding: 3px 16px;
        font-size: 2.9mm;
        font-weight: 900;
        color: #000;
        background: #fff;
    }

    /* =========================================
       Tables (general)
       ========================================= */

    table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 8px;
    }

    td, th {
        color: #000;
        line-height: 1.35;
    }

    /* =========================================
       Invoice Info Table
       ========================================= */

    .info-table {
        width: 100%;
        border-top: 1px solid #000;
        border-bottom: 1px solid #000;
        padding: 8px 0;
        margin-bottom: 10px;
    }

    .info-table .info-row {
        display: flex;
        width: 100%;
        box-sizing: border-box;
        justify-content: space-between;
        padding: 3px 6px;
        font-size: 2.6mm;
        line-height: 1.5;
        gap: 10px;
        direction: {{ dir }};
    }

    .info-table .info-label {
        font-weight: 700;
        white-space: nowrap;
    }

    .info-table .info-value {
        text-align: {% if is_ar %}left{% else %}right{% endif %};
        word-break: break-word;
    }

    .status-partial {
        color: #b91c1c;
        font-weight: 900;
    }

    /* =========================================
       Items Table
       ========================================= */

    .items-table {
        width: 100%;
        border-collapse: collapse;
        border-top: 2px solid #000;
        border-bottom: 2px solid #000;
        direction: {{ dir }};
        table-layout: fixed;
        margin-bottom: 8px;
    }

    .items-table thead th {
        border-bottom: 2px solid #000;
        padding: 8px 3px;
        font-size: 2.7mm;
        font-weight: 900;
        text-align: center !important;
        background: #f0f0f0;
        color: #000;
        vertical-align: middle;
    }

    .items-table tbody td {
        border-bottom: 1px dashed #000;
        padding: 8px 3px;
        text-align: center !important;
        font-size: 2.6mm;
        vertical-align: middle;
    }

    .item-name {
        font-weight: 900;
        word-break: break-word;
        text-align: {% if is_ar %}right{% else %}left{% endif %} !important;
    }

    .item-note {
        font-size: 2.2mm;
        font-weight: 700;
        margin-top: 2px;
    }

    .item-free {
        color: #166534;
        font-weight: 900;
        font-size: 2.2mm;
    }

    .item-discount {
        color: #166534;
        font-size: 2.2mm;
        font-weight: 700;
    }

    .serial-line {
        font-size: 2.1mm;
        color: #444;
        margin-top: 2px;
        text-align: {% if is_ar %}right{% else %}left{% endif %};
    }

    .amount-cell {
        font-weight: 900;
        white-space: nowrap;
    }

    /* =========================================
       Totals
       ========================================= */

    .totals-table {
        margin-top: 8px;
        border-top: 1px solid #000;
        border-bottom: 1px solid #000;
        direction: {{ dir }};
    }

    .totals-table td {
        padding: 6px 10px;
        font-size: 2.6mm;
    }

    .totals-value {
        text-align: {% if is_ar %}left{% else %}right{% endif %};
        font-weight: 700;
        white-space: nowrap;
    }

    .discount-row td {
        color: #166534;
    }

    .total-highlight {
        background: #fff;
        color: #000;
        border-top: 2px solid #000;
        border-bottom: 2px solid #000;
    }

    .total-highlight td {
        padding: 9px 10px;
        font-size: 3.6mm;
        font-weight: 900;
    }

    .outstanding-row td {
        color: #b91c1c;
        font-weight: 900;
        background: #fff8e1;
    }

    /* =========================================
       Payment Methods
       ========================================= */

    .payments-box {
        margin-top: 8px;
        padding: 6px 0;
        border-top: 1px solid #000;
        border-bottom: 1px solid #000;
        direction: {{ dir }};
    }

    .payment-title {
        text-align: center;
        font-size: 2.6mm;
        font-weight: 900;
        margin: 0 10px 5px;
    }

    .payment-row {
        display: flex;
        width: 100%;
        box-sizing: border-box;
        justify-content: space-between;
        padding: 3px 10px;
        font-size: 2.5mm;
        direction: {{ dir }};
    }

    .payment-method {
        font-weight: 700;
    }

    .payment-amount {
        text-align: {% if is_ar %}left{% else %}right{% endif %};
        font-weight: 900;
        white-space: nowrap;
    }

    /* =========================================
       Footer
       ========================================= */

    .thanks-section {
        text-align: center;
        margin-top: 12px;
        font-size: 2.6mm;
        font-weight: 700;
    }

    .social-line {
        text-align: center;
        margin-top: 3px;
        font-size: 2.4mm;
        font-weight: 600;
    }

    .powered-by {
        text-align: center;
        border-top: 1px solid #000;
        padding-top: 6px;
        margin-top: 8px;
        font-size: 2.3mm;
        font-weight: 600;
        letter-spacing: 0.04em;
    }

    .powered-by .brand {
        font-weight: 900;
        letter-spacing: 0.02em;
    }

    .print-space {
        height: 10px;
    }

    @media print {
        body {
            width: 72mm;
            max-width: 72mm;
        }
    }

</style>

{%- set currency_symbol = frappe.db.get_value("Currency", doc.currency, "symbol") or doc.currency -%}
{%- set cashier_user = doc.owner -%}
{%- set cashier_name = frappe.db.get_value("User", cashier_user, "full_name") if cashier_user else None -%}

<!-- ============ Header ============ -->
<div class="header-box">
    <img class="header-logo" src="https://miraaya.com/miraaya-logo.png" alt="MiRAAYA" />
    <span class="invoice-label">{{ labels.invoice_title }}</span>
</div>

<!-- ============ Invoice Info ============ -->
<div class="info-table">
    <div class="info-row">
        <span class="info-label">{{ labels.invoice }}</span>
        <span class="info-value">{{ doc.name }}</span>
    </div>

    <div class="info-row">
        <span class="info-label">{{ labels.date }}</span>
        <span class="info-value">{{ doc.get_formatted("posting_date") }}</span>
    </div>

    {%- if doc.posting_time %}
    <div class="info-row">
        <span class="info-label">{{ labels.time }}</span>
        <span class="info-value">{{ (doc.posting_time|string).split('.')[0] }}</span>
    </div>
    {%- endif -%}

    {%- if cashier_name or cashier_user %}
    <div class="info-row">
        <span class="info-label">{{ labels.cashier }}</span>
        <span class="info-value">{{ cashier_name or cashier_user }}</span>
    </div>
    {%- endif -%}

    {%- if doc.customer_name and doc.customer_name != "Walk-In Customer" %}
    <div class="info-row">
        <span class="info-label">{{ labels.customer }}</span>
        <span class="info-value">{{ doc.customer_name }}</span>
    </div>
    {%- endif -%}

    {%- if doc.pos_profile %}
    <div class="info-row">
        <span class="info-label">{{ labels.pos_profile }}</span>
        <span class="info-value">{{ doc.pos_profile }}</span>
    </div>
    {%- endif -%}

    {%- if doc.status == "Partly Paid" or (doc.outstanding_amount and doc.outstanding_amount > 0 and doc.outstanding_amount < doc.grand_total) %}
    <div class="info-row">
        <span class="info-label">{{ labels.status }}</span>
        <span class="info-value status-partial">{{ labels.partial_payment }}</span>
    </div>
    {%- endif -%}
</div>

<!-- ============ Items ============ -->
<table class="items-table">
    <colgroup>
        <col style="width: 40%;">
        <col style="width: 15%;">
        <col style="width: 20%;">
        <col style="width: 25%;">
    </colgroup>
    <thead>
        <tr>
            <th>{{ labels.item }}</th>
            <th>{{ labels.qty }}</th>
            <th>{{ labels.price }}</th>
            <th>{{ labels.amount }}</th>
        </tr>
    </thead>
    <tbody>
        {%- for item in doc.items -%}
        <tr>
            <td class="item-name">
                {{ item.item_name }}
                {%- if item.is_free_item -%}
                <div class="item-free">({{ labels.free }})</div>
                {%- endif -%}
                {%- if item.discount_percentage or item.discount_amount -%}
                <div class="item-discount">
                    {{ labels.discount }}{%- if item.discount_percentage -%} ({{ "%.1f"|format(item.discount_percentage) }}%){%- endif -%}
                    -{{ currency_symbol }} {{ "%.2f"|format(item.discount_amount or 0) }}
                </div>
                {%- endif -%}
                {%- if item.serial_no -%}
                <div class="serial-line">{{ labels.serial }}: {{ item.serial_no | replace("\n", ", ") }}</div>
                {%- endif -%}
            </td>
            <td>{{ "%.0f"|format(item.qty) }}</td>
            <td>
                {%- if item.is_free_item -%}
                {{ labels.free }}
                {%- else -%}
                {{ "%.2f"|format(item.price_list_rate or item.rate) }}
                {%- endif -%}
            </td>
            <td class="amount-cell">
                {%- if item.is_free_item -%}
                {{ currency_symbol }} 0.00
                {%- else -%}
                {{ "%.2f"|format(item.amount) }}
                {%- endif -%}
            </td>
        </tr>
        {%- endfor -%}
    </tbody>
</table>

<!-- ============ Totals ============ -->
<table class="totals-table">
    <tr>
        <td width="60%">{{ labels.subtotal }}</td>
        <td width="40%" class="totals-value">{{ currency_symbol }} {{ "%.2f"|format(doc.net_total or doc.total) }}</td>
    </tr>

    {%- if doc.total_taxes_and_charges and doc.total_taxes_and_charges > 0 -%}
    <tr>
        <td>{{ labels.tax }}</td>
        <td class="totals-value">{{ currency_symbol }} {{ "%.2f"|format(doc.total_taxes_and_charges) }}</td>
    </tr>
    {%- endif -%}

    {%- for t in doc.taxes if t.tax_amount and t.tax_amount > 0 and (not doc.total_taxes_and_charges) -%}
    <tr>
        <td>{{ t.description or t.account_head or labels.tax }}</td>
        <td class="totals-value">{{ currency_symbol }} {{ "%.2f"|format(t.tax_amount) }}</td>
    </tr>
    {%- endfor -%}

    {%- if doc.discount_amount -%}
    <tr class="discount-row">
        <td>
            {{ labels.discount }}
            {%- if doc.additional_discount_percentage -%}
            ({{ "%.1f"|format(doc.additional_discount_percentage) }}%)
            {%- endif -%}
        </td>
        <td class="totals-value">-{{ currency_symbol }} {{ "%.2f"|format(doc.discount_amount|abs) }}</td>
    </tr>
    {%- endif -%}

    <tr class="total-highlight">
        <td>{{ labels.total }}</td>
        <td class="totals-value">{{ currency_symbol }} {{ "%.2f"|format(doc.grand_total) }}</td>
    </tr>
</table>

<!-- ============ Payment Methods ============ -->
{%- set paid_rows = doc.payments | selectattr("amount", "greaterthan", 0) | list if doc.payments else [] -%}
{%- if paid_rows -%}
<div class="payments-box">
    <div class="payment-title">{{ labels.payment_methods }}</div>
    {%- for payment in paid_rows -%}
    <div class="payment-row">
        <span class="payment-method">{{ _(payment.mode_of_payment) }}</span>
        <span class="payment-amount">{{ currency_symbol }} {{ "%.2f"|format(payment.amount) }}</span>
    </div>
    {%- endfor -%}

    <div class="payment-row" style="margin-top:4px; border-top:1px solid #ccc; padding-top:4px;">
        <span class="payment-method">{{ labels.total_paid }}</span>
        <span class="payment-amount">{{ currency_symbol }} {{ "%.2f"|format(doc.paid_amount or 0) }}</span>
    </div>

    {%- if doc.change_amount and doc.change_amount > 0 -%}
    <div class="payment-row">
        <span class="payment-method">{{ labels.change }}</span>
        <span class="payment-amount">{{ currency_symbol }} {{ "%.2f"|format(doc.change_amount) }}</span>
    </div>
    {%- endif -%}

    {%- if doc.outstanding_amount and doc.outstanding_amount > 0 -%}
    <div class="payment-row" style="color:#b91c1c; font-weight:900;">
        <span class="payment-method">{{ labels.balance_due }}</span>
        <span class="payment-amount">{{ currency_symbol }} {{ "%.2f"|format(doc.outstanding_amount) }}</span>
    </div>
    {%- endif -%}
</div>
{%- endif -%}

<!-- ============ Footer ============ -->
<div class="thanks-section">{{ labels.thank_you }} &#10084;</div>
<div class="social-line">miraaya.com</div>

<div class="powered-by">
    {{ labels.powered_by }} <span class="brand">Brainwise</span>
</div>

<div class="print-space"></div>
